parameters.jsCode:
const geminiResponse = $input.item.json;
const userMessage = $('Webhook').item.json.body.message;
const products = $('Get Products').item.json.results || [];

let botMessage = "Xin lỗi, tôi không thể trả lời lúc này.";

try {
  if (geminiResponse.candidates && geminiResponse.candidates[0]) {
    botMessage = geminiResponse.candidates[0].content.parts[0].text;
  }
} catch (error) {
  console.error('Error parsing Gemini response:', error);
}

// Format products for display if relevant
let productList = [];
const lowerMessage = userMessage.toLowerCase();

if (lowerMessage.includes('giá') || lowerMessage.includes('bao nhiêu') || 
    lowerMessage.includes('price') || lowerMessage.includes('sản phẩm')) {
  productList = products.slice(0, 5).map(p => ({
    name: p.name,
    price: `${p.price.toLocaleString()} VNĐ/${p.unit}`,
    available: p.in_stock
  }));
}

return {
  json: {
    success: true,
    message: botMessage,
    products: productList,
    timestamp: Date.now()
  }
};
